using System.ComponentModel.DataAnnotations;

namespace MoneyExchange.Api.Models.Entities;

/// <summary>
/// A one-time activation code that grants (or extends) a paid <b>Pro</b> plan when redeemed.
/// Codes are generated by the business (out of band / after payment) and given to a customer whose
/// trial or paid plan has expired; redeeming one sets <see cref="User.PlanPaidUntilUtc"/> to
/// <see cref="DurationDays"/> days out and re-opens access to the app + on-device forwarding.
/// </summary>
public class ActivationCode
{
    public int Id { get; set; }

    /// <summary>The redeemable code (unique, case-insensitive; stored upper-cased).</summary>
    [Required, MaxLength(32)]
    public string Code { get; set; } = string.Empty;

    /// <summary>How many days of Pro access this code grants when redeemed (default 30 = one month).</summary>
    public int DurationDays { get; set; } = 30;

    /// <summary>
    /// How many <b>minutes</b> of Pro access this code grants — the precise unit the admin sets (so a
    /// 2-minute test code is possible). When &gt; 0 it takes precedence over <see cref="DurationDays"/>
    /// on redeem; 0 means "fall back to DurationDays" (for older codes minted before this field).
    /// </summary>
    public int DurationMinutes { get; set; }

    /// <summary>
    /// The phone number this code was issued to (normalized), or null for a bearer code that anyone
    /// can redeem. When set, only the account whose <see cref="User.PhoneNumber"/> matches may redeem
    /// it — so a code WhatsApp'd to one customer is useless if leaked/forwarded to someone else.
    /// </summary>
    [MaxLength(20)]
    public string? AssignedToPhone { get; set; }

    /// <summary>
    /// When this code stops being redeemable, or null for no expiry. A code left unredeemed past this
    /// instant is dead, limiting the blast radius of a leaked-but-unused code.
    /// </summary>
    public DateTime? ExpiresAtUtc { get; set; }

    /// <summary>True once the code has been consumed; a code can only be redeemed once.</summary>
    public bool IsRedeemed { get; set; }

    /// <summary>The <see cref="User"/> that redeemed this code, if any.</summary>
    public int? RedeemedByUserId { get; set; }

    public DateTime? RedeemedAtUtc { get; set; }

    public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow;
}
